    val zh: Map<String, String> by lazy { parse(RAW_ZH) }

    val all: Map<String, Map<String, String>> by lazy {
        mapOf("ru" to ru, "en" to en, "be" to be, "uk" to uk, "zh" to zh)
    }

    val languageNames: Map<String, String> = mapOf(
        "ru" to "Русский", "en" to "English", "be" to "Беларуская", "uk" to "Українська", "zh" to "中文",
    )

    /** Строки, которых нет в APK 1.1.5, но нужны порту. */
    val extra: Map<String, Map<String, String>> = mapOf(
        "extra_expired" to mapOf(
            "ru" to "срок истёк", "en" to "expired",
            "be" to "тэрмін скончыўся", "uk" to "термін минув", "zh" to "已过期",
        ),
    )

    private fun parse(raw: String): Map<String, String> {
        val map = HashMap<String, String>(512)
        raw.split('\u0002').forEach { entry ->
            if (entry.isEmpty()) return@forEach
            val index = entry.indexOf('\u0001')
            if (index <= 0) return@forEach
            map[entry.substring(0, index)] = entry.substring(index + 1)
        }
        return map
    }

    /** Подстановка %1$s / %1$d — как в оригинале. */
    fun format(pattern: String, vararg args: Any?): String {
        var result = pattern
        args.forEachIndexed { index, arg ->
            val value = arg?.toString() ?: ""
            result = result.replace("%${index + 1}\$s", value).replace("%${index + 1}\$d", value)
        }
        return result
    }
